+const MAX_PAGE = 100;
+
+function limitOffset(page = 1, pageSize = 20) {
+  const size = Math.min(Math.max(1, pageSize | 0), MAX_PAGE);
+  const p = Math.max(1, page | 0);
+  return { limit: size, offset: (p - 1) * size };
+}
